package org.apache.commons.math.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.MathArithmeticException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.OpenIntToDoubleHashMap.Iterator;
import org.apache.commons.math.util.OpenIntToDoubleHashMap;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for OpenMapRealVector#append(double[] a)
 */
public class OpenMapRealVector_append_TriageGen2Test {

    @Test
    public void testAppendWithValidArray() {
        // Initialize vector with some values
        double[] initialData = {1.0, 0.0, 2.0};
        OpenMapRealVector vector = new OpenMapRealVector(initialData);

        // Data to append
        double[] toAppend = {3.0, 4.0};

        // Perform append
        OpenMapRealVector result = vector.append(toAppend);

        // Verify dimension
        Assert.assertEquals("Dimension should be sum of original and appended", 
                vector.getDimension() + toAppend.length, result.getDimension());

        // Verify values
        Assert.assertEquals(1.0, result.getEntry(0), 1e-10);
        Assert.assertEquals(0.0, result.getEntry(1), 1e-10);
        Assert.assertEquals(2.0, result.getEntry(2), 1e-10);
        Assert.assertEquals(3.0, result.getEntry(3), 1e-10);
        Assert.assertEquals(4.0, result.getEntry(4), 1e-10);
    }

    @Test
    public void testAppendWithEmptyArray() {
        double[] initialData = {1.0, 2.0};
        OpenMapRealVector vector = new OpenMapRealVector(initialData);

        double[] toAppend = new double[0];

        OpenMapRealVector result = vector.append(toAppend);

        Assert.assertEquals("Dimension should remain the same", 
                vector.getDimension(), result.getDimension());
        Assert.assertEquals(2, result.getDimension());
        Assert.assertEquals(1.0, result.getEntry(0), 1e-10);
        Assert.assertEquals(2.0, result.getEntry(1), 1e-10);
    }

    @Test
    public void testAppendToEmptyVector() {
        OpenMapRealVector vector = new OpenMapRealVector(0);
        double[] toAppend = {5.5, 6.6};

        OpenMapRealVector result = vector.append(toAppend);

        Assert.assertEquals(2, result.getDimension());
        Assert.assertEquals(5.5, result.getEntry(0), 1e-10);
        Assert.assertEquals(6.6, result.getEntry(1), 1e-10);
    }

    @Test
    public void testAppendWithSparseData() {
        // Testing sparse behavior via append
        OpenMapRealVector vector = new OpenMapRealVector(3);
        vector.setEntry(0, 1.0);

        double[] toAppend = {0.0, 9.9}; // 0.0 is default/sparse

        OpenMapRealVector result = vector.append(toAppend);

        Assert.assertEquals(5, result.getDimension());
        Assert.assertEquals(1.0, result.getEntry(0), 1e-10);
        Assert.assertEquals(0.0, result.getEntry(1), 1e-10);
        Assert.assertEquals(0.0, result.getEntry(2), 1e-10);
        Assert.assertEquals(9.9, result.getEntry(3), 1e-10);
    }

    @Test(expected = NullPointerException.class)
    public void testAppendNull() {
        OpenMapRealVector vector = new OpenMapRealVector(2);
        vector.append(null);
    }

    @Test
    public void testAppendImmutability() {
        // Ensure the original vector is not modified
        double[] initialData = {1.0, 2.0};
        OpenMapRealVector vector = new OpenMapRealVector(initialData);
        double[] toAppend = {3.0};

        vector.append(toAppend);

        Assert.assertEquals("Original vector dimension should not change", 2, vector.getDimension());
        Assert.assertEquals(2.0, vector.getEntry(1), 1e-10);
    }
}
